const body = $json.body ?? {};
const mode = String(body.mode ?? '').trim();
const allowed = ['skill.read','skill.save','skill.ingest','skill.interview'];
if (!allowed.includes(mode)) return [{json:{ok:false,statusCode:400,error:'Unsupported operation. Use skill.read, skill.save, skill.ingest or skill.interview.'}}];
return [{json:{ok:true,mode,body,agentTrace:[],receivedAt:new Date().toISOString()}}];

if (!$json.ok || $json.mode !== 'skill.ingest') return items;
const extracted = Array.isArray($json.body.extracted) ? $json.body.extracted.slice(0,20) : [];
const fluff = /other duties|arrive on time|as assigned|punctual|team player/gi;
const sources = extracted.map((source,index)=>({id:index+1,name:String(source.name||'evidence'),content:String(source.content||'').replace(fluff,'').slice(0,120000)})).filter(source=>source.content.trim());
if (!sources.length) return [{json:{...$json,ok:false,statusCode:400,error:'No usable role evidence supplied.'}}];
return [{json:{...$json,sources,agentTrace:[...$json.agentTrace,{agent:'Evidence auditor',result:`${sources.length} governed sources retained`}]}}];

if (!$json.ok || $json.mode !== 'skill.ingest') return items;
const text = $json.sources.map(source=>source.content).join(' ');
const statements = text.split(/[.!?\n]+/).map(value=>value.trim()).filter(value=>value.length>20).slice(0,24);
const patterns=[[/dashboard|visuali[sz]|report/i,'Data Visualization'],[/taxonomy|skill architecture|skill framework/i,'Skill Taxonomy Design'],[/stakeholder|influence|align/i,'Stakeholder Alignment'],[/analy[sz]|insight|metric/i,'Data Analysis'],[/project|deliver|milestone/i,'Project Delivery'],[/facilitat|workshop|interview/i,'Structured Facilitation']];
const candidates=[];
for (const statement of statements) { const match=patterns.find(([pattern])=>pattern.test(statement)); if(match) candidates.push({name:match[1],evidence:statement,source:'role evidence'}); }
if(!candidates.length && statements[0]) candidates.push({name:'Role-specific Capability',evidence:statements[0],source:'role evidence'});
return [{json:{...$json,candidates,agentTrace:[...$json.agentTrace,{agent:'Semantic extractor',result:`${candidates.length} action-object-outcome candidates found`}]}}];

if (!$json.ok || $json.mode !== 'skill.ingest') return items;
const seen=new Set(); const proposals=[];
for(const candidate of $json.candidates||[]){const key=String(candidate.name).toLowerCase();if(seen.has(key))continue;seen.add(key);proposals.push({...candidate,id:`REV-${Date.now()}-${proposals.length+1}`,description:`Ability to apply ${candidate.name} to produce observable role outcomes.`,dimension:/stakeholder|facilitation/i.test(candidate.name)?'competency':'technical',confidence:Math.min(95,72+proposals.length*5)});}
return [{json:{...$json,proposals,agentTrace:[...$json.agentTrace,{agent:'Skill normalizer',result:`${proposals.length} atomic capabilities retained after de-layering`}]}}];

if (!$json.ok || $json.mode !== 'skill.ingest') return items;
const proposals=($json.proposals||[]).map(item=>({...item,groupId:/data|visual/i.test(item.name)?'GRP-DA':'GRP-SBO',futureRelevance:'core',observability:`Demonstrates ${item.name} through a concrete work product or critical incident.`}));
return [{json:{...$json,proposals,agentTrace:[...$json.agentTrace,{agent:'Taxonomy matcher',result:'Hierarchy fit, dimension and duplicate candidates assessed'}]}}];

if (!$json.ok || $json.mode !== 'skill.ingest') return items;
const roleTitle=String($json.body.roleTitle||'Untitled role');
const profile={title:roleTitle,recommendedSkillCount:'8-12',composition:'5-6 technical · 3-4 behavioral · 1-2 traits/drivers',proficiencyLevels:['Awareness','Application','Mastery','Strategic / Expert']};
return [{json:{...$json,profile,agentTrace:[...$json.agentTrace,{agent:'Profile composer',result:'Profile constraints and proficiency guidance applied'}]}}];

if (!$json.ok) return items;
const store=$getWorkflowStaticData('global');
const names=['Action Oriented','Ensures Accountability','Manages Ambiguity','Attracts Top Talent','Business Insight','Collaborates','Communicates Effectively','Manages Complexity','Manages Conflict','Courage','Customer Focus','Decision Quality','Develops Talent','Values Differences','Directs Work','Drives Engagement','Financial Acumen','Global Perspective','Cultivates Innovation','Interpersonal Savvy','Builds Networks','Nimble Learning','Organizational Savvy','Persuades','Plans and Aligns','Being Resilient','Resourcefulness','Drives Results','Demonstrates Self-Awareness','Self-Development','Situational Adaptability','Balances Stakeholders','Strategic Mindset','Builds Effective Teams','Tech Savvy','Instills Trust','Drives Vision and Purpose','Optimizes Work Processes'];
const factor=n=>[5,8,12,17,18,19,33,35].includes(n)?'Thought':[1,2,11,15,25,27,28,32,38].includes(n)?'Results':[4,6,7,9,13,14,16,20,21,23,24,34,36,37].includes(n)?'People':'Self';
if(!store.workspace)store.workspace={schemaVersion:1,revision:1,updatedAt:new Date().toISOString(),domains:[{id:'DOM-DT',name:'Digital & Technology',description:'Digital products, data and technology capabilities.',status:'approved'},{id:'DOM-PC',name:'People & Culture',description:'Organisation, talent and people leadership capabilities.',status:'approved'}],groups:[{id:'GRP-DA',domainId:'DOM-DT',name:'Data & Analytics',description:'Data products, insight and decision support.',status:'approved'},{id:'GRP-SBO',domainId:'DOM-PC',name:'Skill-based Organisation',description:'Skill architecture and workforce activation.',status:'approved'}],skills:[],profiles:[],interviews:[],reviewQueue:[],kfla:names.map((name,index)=>({id:`KFLA-${String(index+1).padStart(2,'0')}`,number:index+1,name,factor:factor(index+1),enabled:true,definition:'',source:'public-name'}))};
const workspace=store.workspace;
if($json.mode==='skill.read')return[{json:{ok:true,workspace,message:'Skill workspace loaded from the active n8n orchestrator.'}}];
if($json.mode==='skill.save'){const candidate=$json.body.workspace;if(!candidate||candidate.schemaVersion!==1||!Array.isArray(candidate.skills)||!Array.isArray(candidate.kfla))return[{json:{ok:false,statusCode:400,error:'Invalid Skill Designer workspace.'}}];candidate.updatedAt=new Date().toISOString();store.workspace=candidate;return[{json:{ok:true,workspace:candidate,message:`Skill workspace revision ${candidate.revision} persisted.`}}];}
if($json.mode==='skill.interview'){const body=$json.body;let interview=workspace.interviews.find(item=>item.id===body.interviewId);if(!interview){interview={id:`INT-${Date.now()}`,roleTitle:String(body.roleTitle||'Untitled role'),stakeholder:String(body.stakeholder||'Manager'),interviewee:String(body.interviewee||''),status:'in_progress',currentQuestion:0,responses:[]};workspace.interviews.push(interview);}interview.responses.push({question:`Guided question ${interview.currentQuestion+1}`,answer:String(body.answer||'')});interview.currentQuestion=Math.min(4,interview.currentQuestion+1);if(interview.currentQuestion>=4)interview.status='complete';workspace.updatedAt=new Date().toISOString();store.workspace=workspace;return[{json:{ok:true,workspace,interview,message:interview.status==='complete'?'Interview completed and routed to review.':'Interview progress saved.'}}];}
const review=($json.proposals||[]).map(item=>({id:item.id,title:item.name,type:'new_skill',summary:`Normalized from role evidence and mapped to ${item.dimension}.`,confidence:item.confidence,evidence:item.evidence,status:'pending'}));workspace.reviewQueue.push(...review);workspace.updatedAt=new Date().toISOString();store.workspace=workspace;return[{json:{ok:true,workspace,proposals:review,agentTrace:[...$json.agentTrace,{agent:'Governance gate',result:`${review.length} proposals routed to human review`}],message:`${review.length} governed proposals added to review.`}}];
